          type: "apiToken",
          apiToken,
          apiBaseUrl,
          source: { type: source },
        };
  },
  readEnvironment,
  environment: [
    {
      name: "AXIOM_TOKEN",
      required: true,
      secret: true,
      alternatives: ["AXIOM_API_KEY"],
      description: "Personal access token or API token.",
