import { declareTaxKitAxiomResources } from "@taxkit/infrastructure/axiom";
import {
  TaxKitObservability,
  requireProductionStage,
  sharedDatasets,
  telemetryStackProps,
} from "@taxkit/infrastructure/telemetry";
import { Effect } from "effect";

// TaxKit owns its ingest token and dashboards; Site continues to own the
// three shared datasets.
export default TaxKitObservability.make(
  telemetryStackProps,
  Effect.gen(function* () {
    yield* requireProductionStage;
    const { dashboardCount } =
      yield* declareTaxKitAxiomResources(sharedDatasets);
    return { dashboardCount };
  })
);

