import {
  TaxKitTraceExport,
  requireProductionStage,
  telemetryStackProps,
} from "@taxkit/infrastructure/telemetry";
import {
  declareTaxKitLogDestination,
  declareTaxKitTraceDestination,
} from "@taxkit/infrastructure/trace-export";
import { Effect } from "effect";

// Separate state keeps dashboard updates independent of Cloudflare
// observability permissions.
export default TaxKitTraceExport.make(
  telemetryStackProps,
  Effect.gen(function* () {
    yield* requireProductionStage;
    const traces = yield* declareTaxKitTraceDestination();
    const logs = yield* declareTaxKitLogDestination();
    // Production Workers read these persisted names. Never output the
    // destinations' headers or configuration.
    return {
      logsDestinationName: logs.name,
      tracesDestinationName: traces.name,
    };
  })
);

