import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import { recordStateStoreInit } from "../Telemetry/Metrics.ts";
import { STATE_STORE_VERSION } from "./HttpStateApi.ts";
import type { ResourceState } from "./ResourceState.ts";
import { State, type PersistedState } from "./State.ts";

type StackId = string;
type StageId = string;
type Fqn = string;

export const inMemoryState = (
  initialState: Record<StackId, Record<StageId, Record<Fqn, ResourceState>>> = {},
  initialOutputs: Record<StackId, Record<StageId, unknown>> = {},
) =>
  Layer.effect(
    State,
    Effect.cached(InMemoryService(initialState, initialOutputs).pipe(recordStateStoreInit)),
  );

export const InMemoryService = (
  state: Record<StackId, Record<StageId, Record<Fqn, ResourceState>>> = {},
  outputs: Record<StackId, Record<StageId, unknown>> = {},
) =>
  State.of(
    Effect.succeed({
      id: "inmemory",
      getVersion: () => Effect.succeed(STATE_STORE_VERSION),
      listStacks: () => Effect.succeed(Array.from(Object.keys(state))),
      listStages: (stack: string) =>
        Effect.succeed(Array.from(stack in state ? Object.keys(state[stack]) : [])),
      get: ({ stack, stage, fqn }: { stack: string; stage: string; fqn: string }) =>
        Effect.succeed(state[stack]?.[stage]?.[fqn]),
      getReplacedResources: ({ stack, stage }: { stack: string; stage: string }) =>
        Effect.succeed(
          Array.from(Object.values(state[stack]?.[stage] ?? {}) ?? []).filter(
            (s) => s.status === "replaced",
          ),
        ),
      set: <V extends PersistedState>({
        stack,
        stage,
        fqn,
        value,
      }: {
        stack: string;
        stage: string;
        fqn: string;
        value: V;
      }) =>
        Effect.sync(() => {
          const stackState = (state[stack] ??= {});
          const stageState = (stackState[stage] ??= {});
          stageState[fqn] = value as ResourceState;
          return value;
        }),
      delete: ({ stack, stage, fqn }: { stack: string; stage: string; fqn: string }) =>
        Effect.sync(() => delete state[stack]?.[stage]?.[fqn]),
      deleteStack: ({ stack, stage }: { stack: string; stage?: string }) =>
        Effect.sync(() => {
          if (stage === undefined) {
            delete state[stack];
            delete outputs[stack];
          } else {
            delete state[stack]?.[stage];
            delete outputs[stack]?.[stage];
          }
        }),
      list: ({ stack, stage }: { stack: string; stage: string }) =>
        Effect.succeed(Array.from(Object.keys(state[stack]?.[stage] ?? {}) ?? [])),
      getOutput: ({ stack, stage }: { stack: string; stage: string }) =>
        Effect.succeed(outputs[stack]?.[stage]),
      setOutput: ({ stack, stage, value }: { stack: string; stage: string; value: unknown }) =>
        Effect.sync(() => {
          const stackOutputs = (outputs[stack] ??= {});
          stackOutputs[stage] = value;
          return value;
        }),
    }),
  );

import type { NamespaceNode } from "../Namespace.ts";
import type { ProviderMode } from "../ProviderMode.ts";
import type { RemovalPolicy } from "../RemovalPolicy.ts";
import type { ResourceBinding } from "../Resource.ts";

export type ResourceState =
  | CreatingResourceState
  | CreatedResourceState
  | UpdatingReourceState
  | UpdatedResourceState
  | DeletingResourceState
  | ReplacingResourceState
  | ReplacedResourceState;

export type Props = Record<string, any>;
export type Attr = Record<string, any>;

export type ResourceStatus = ResourceState["status"];
export type ReplacementResourceState = ReplacingResourceState | ReplacedResourceState;
export type ReplacementOldResourceState =
  | CreatingResourceState
  | CreatedResourceState
  | UpdatingReourceState
  | UpdatedResourceState
  | DeletingResourceState
  | ReplacementResourceState;

interface BaseResourceState {
  /**
   * Discriminator vs {@link ActionState}. Optional for back-compat: legacy
   * persisted rows have no `kind` field and are implicitly resources.
   */
  readonly kind?: "resource";
  /** Type of the Resource (e.g. AWS.Lambda.Function) */
  resourceType: string;
  /** Namespace of the Resource */
  namespace: NamespaceNode | undefined;
  /** Fully Qualified Name (namespace path + logical ID) */
  fqn: string;
  /** Logical ID of the Resource (stable across creates, updates, deletes and replaces) */
  logicalId: string;
  /** A unique randomly generated token used to seed ID generation (only changes when replaced) */
  instanceId: string;
  /** The version of the provider that was used to create/update the resource. */
  providerVersion: number;
  /** Current status of the logical Resource */
  status: ResourceStatus;
  /** List of FQNs of resources that depend on this resource */
  downstream: string[];
  /** List of Bindings attached to this Resource */
  bindings: ResourceBinding[];
  /** Desired state (input props) of this Resource */
  props?: Props;
  /** The output attributes of this Resource (if it has been created) */
  attr?: Attr;
  /** The removal policy of the resource */
  removalPolicy?: RemovalPolicy["Service"];
  /** Attr-less lookup could recover the predecessor migrated away from this FQN. */
  adoptionBlocked?: "migrated-fqn";
  /**
   * The {@link ProviderMode} this resource was last reconciled with.
   *
   * Stamped by Apply on every commit for resources whose provider
   * distinguishes modes (`ProviderLayer.dual`). Plan treats a mismatch
   * between the persisted mode and the resolved desired mode as a
   * **replacement**, and deletion always uses the provider variant of the
   * mode that created the row.
   *
   * `undefined` means either a mode-agnostic provider (single
   * implementation serves both dev and deploy) or a legacy row written
   * before modes were persisted — both acted on the real cloud, so an
   * unstamped row is assumed **live**, unless its attrs carry a local
   * identity marker (`dev:`-prefixed ids) proving it was reconciled
   * locally, in which case it is assumed **local** (see `stampedMode`).
   * Same-mode runs see no churn; a run in the other mode replaces it like
   * any stamped row.
   */
  providerMode?: ProviderMode;
}

