import { BunServices } from "@effect/platform-bun";
import { describe, expect, it } from "@effect/vitest";
import { AlchemyContext } from "alchemy/AlchemyContext";
import { ArtifactStore, createArtifactStore } from "alchemy/Artifacts";
import { AuthProviders } from "alchemy/Auth/AuthProvider";
import { CredentialsStore } from "alchemy/Auth/Credentials";
import { ProfileStore } from "alchemy/Auth/Profile";
import * as Axiom from "alchemy/Axiom";
import * as Cloudflare from "alchemy/Cloudflare";
import { ObservabilityDestination } from "alchemy/Cloudflare/Workers";
import { layerNonInteractive } from "alchemy/Interaction";
import * as Output from "alchemy/Output";
import * as Plan from "alchemy/Plan";
import * as Provider from "alchemy/Provider";
import * as Stack from "alchemy/Stack";
import { Stage } from "alchemy/Stage";
import { inMemoryState } from "alchemy/State";
import {
  Array,
  Cause,
  Effect,
  Exit,
  Layer,
  Order,
  Record,
  Redacted,
  Ref,
  Schema,
} from "effect";
import { HttpClient } from "effect/http";

import { declareTaxKitObservability } from "./axiom/resources.js";
import { declareTaxKitTraceExport } from "./trace-export.js";

// A synthetic stand-in for the retained ingest token. It is not a credential.
const ingestSentinel = "synthetic-ingest-token-fixture";

const environment = Effect.provide(
  Layer.mergeAll(
    BunServices.layer,
    Layer.succeed(ArtifactStore, createArtifactStore()),
    Layer.succeed(AuthProviders, {}),
    layerNonInteractive(),
    Layer.succeed(
      ProfileStore,
      ProfileStore.of({
        createProfile: () => Effect.die("Unexpected profile write"),
        current: Effect.die("Unexpected profile read"),
        deleteProfile: () => Effect.die("Unexpected profile write"),
        deleteProviderConfig: () => Effect.die("Unexpected profile write"),
        ensureProfile: () => Effect.die("Unexpected profile write"),
        getProfile: () => Effect.die("Unexpected profile read"),
        loadProviderConfig: () => Effect.die("Unexpected profile read"),
        readManifest: Effect.die("Unexpected profile read"),
        renameProfile: () => Effect.die("Unexpected profile write"),
        setProviderConfig: () => Effect.die("Unexpected profile write"),
      })
    ),
    Layer.succeed(
      CredentialsStore,
      CredentialsStore.of({
        delete: () => Effect.die("Unexpected credential write"),
        deleteProfile: () => Effect.die("Unexpected credential write"),
        read: () => Effect.die("Unexpected credential read"),
        write: () => Effect.die("Unexpected credential write"),
      })
    ),
    HttpClient.layerMergedContext(
      Effect.succeed(
        HttpClient.make(() => Effect.die("Unexpected network access"))
      )
    )
  )
);
const localContext = {
  adopt: false,
  dev: false,
  dotAlchemy: "tmp/telemetry-graph-proof",
};

// Persisted records of the foreign resources the telemetry stacks reference:
// Site's two signal datasets and TaxKit's retained ingest token.
const persisted = (
  resourceType: string,
  logicalId: string,
  attr: Record<string, unknown>
) => ({
  attr,
  bindings: [],
  downstream: [],
  fqn: logicalId,
  instanceId: `proof-${logicalId}`,
  logicalId,
  namespace: undefined,
  providerVersion: 0,
  resourceType,
  status: "created" as const,
});
const foreignState = {
  CooperCorbettSiteCloudflare: {
    prod: {
      SiteProdLogsDataset: persisted("Axiom.Dataset", "SiteProdLogsDataset", {
        name: "site-prod-logs",
        otelLogsEndpoint: "https://axiom.example.test/v1/logs",
      }),
      SiteProdTracesDataset: persisted(
        "Axiom.Dataset",
        "SiteProdTracesDataset",
        {
          name: "site-prod-traces",
          otelTracesEndpoint: "https://axiom.example.test/v1/traces",
        }
      ),
    },
  },
  TaxKitObservability: {
    prod: {
      TaxKitTelemetryIngest: persisted(
        "Axiom.ApiToken",
        "TaxKitTelemetryIngest",
        { id: "proof-token", token: Redacted.make(ingestSentinel) }
      ),
    },
  },
};

const telemetryFixture = Effect.fnUntraced(function* (
  stack: "observability" | "trace-export",
  stage: string
) {
  const providerWrites = yield* Ref.make(0);
  const forbiddenWrite = Ref.update(providerWrites, (count) => count + 1).pipe(
    Effect.andThen(Effect.die("Provider writes are forbidden in graph proof"))
  );
  const refuseWrites = {
    delete: () => forbiddenWrite,
    diff: () => Effect.void,
    read: ({ output }: { readonly output: unknown }) => Effect.succeed(output),
    reconcile: () => forbiddenWrite,
  };
  const stateLayer = inMemoryState(foreignState);
  const compiled = yield* (
    stack === "observability"
      ? Stack.make({
          name: "TaxKitObservability",
          providers: Layer.effect(
            Axiom.Providers,
            Provider.collection([Axiom.ApiToken, Axiom.Dashboard]).pipe(
              Effect.provide(
                Layer.mergeAll(
                  Provider.succeed(Axiom.ApiToken, refuseWrites),
                  Provider.succeed(Axiom.Dashboard, refuseWrites)
                )
              )
            )
          ),
          state: stateLayer,
        })(declareTaxKitObservability)
      : Stack.make({
          name: "TaxKitTraceExport",
          providers: Layer.effect(
            Cloudflare.Providers,
            Provider.collection([ObservabilityDestination]).pipe(
              Effect.provide(
                Provider.succeed(ObservabilityDestination, refuseWrites)
              )
            )
          ),
          state: stateLayer,
        })(declareTaxKitTraceExport)
  ).pipe(Effect.provideService(Stage, stage), Effect.exit);
  return { compiled, providerWrites };
});

const planned = Effect.fnUntraced(function* (
  stack: "observability" | "trace-export"
) {
  const fixture = yield* telemetryFixture(stack, "prod");
  const compiled = yield* fixture.compiled;
  const plan = yield* Plan.make(compiled).pipe(
    Effect.provideContext(compiled.services),
    Effect.timeout("1 second")
  );
  return {
    compiled,
    plan,
    providerWrites: yield* Ref.get(fixture.providerWrites),
  };
});

const Query = Schema.Struct({ query: Schema.Struct({ apl: Schema.String }) });

describe("production-only telemetry stacks", () => {
  it.live.each([
    ["observability", "pr-214"],
    ["observability", "dev_ci_user"],
    ["trace-export", "pr-214"],
    ["trace-export", "dev_ci_user"],
  ] as const)("%s refuses stage %s before any resource", ([stack, stage]) =>
    Effect.gen(function* () {
      const fixture = yield* telemetryFixture(stack, stage);
      expect(Exit.isFailure(fixture.compiled)).toBe(true);
      if (Exit.isFailure(fixture.compiled)) {
        expect(Cause.pretty(fixture.compiled.cause)).toContain(
          "TaxKit telemetry stacks require the prod stage"
        );
      }
      expect(yield* Ref.get(fixture.providerWrites)).toBe(0);
    }).pipe(
      Effect.provideService(AlchemyContext, localContext),
      environment,
      Effect.scoped
    )
  );

  it.live("plans a retained ingest-only token and four dashboards", () =>
    Effect.gen(function* () {
      const { compiled, plan, providerWrites } = yield* planned(
        "observability"
      );
      expect(providerWrites).toBe(0);
      expect(Array.sort(Record.keys(plan.resources), Order.String)).toEqual([
        "TaxKitRequestFailures",
        "TaxKitRequestLatency",
        "TaxKitRequestOverview",
        "TaxKitTelemetryHealth",
        "TaxKitTelemetryIngest",
      ]);
      expect(
        Array.every(
          Record.values(plan.resources),
          ({ action }) => action === "create"
        )
      ).toBe(true);
      expect(
        Array.every(
          Record.values(compiled.resources),
          (resource) => resource.RemovalPolicy === "retain"
        )
      ).toBe(true);
      // Ingest only, on exactly Site's three shared datasets.
      const token = Record.get(compiled.resources, "TaxKitTelemetryIngest");
      expect(token._tag === "Some" ? token.value.Props : undefined).toEqual({
        datasetCapabilities: {
          "site-prod-logs": { ingest: ["create"] },
          "site-prod-metrics": { ingest: ["create"] },
          "site-prod-traces": { ingest: ["create"] },
        },
        description: "Ingest TaxKit Production Worker telemetry only",
        name: "taxkit-telemetry-ingest",
      });
      expect(compiled.output).toEqual({ dashboardCount: 4 });
      // Every chart reads only TaxKit's own records in the shared logs dataset
      // and never a URL, header or calculation field.
      const dashboards = yield* Effect.forEach(
        [
          "TaxKitRequestOverview",
          "TaxKitRequestFailures",
          "TaxKitRequestLatency",
          "TaxKitTelemetryHealth",
        ],
        (id) =>
          Record.get(compiled.resources, id).pipe(
            Effect.fromOption,
            Effect.flatMap((resource) =>
              Output.evaluate(
                { props: resource.Props, uid: resource.Props.uid },
                {}
              )
            ),
            Effect.provideContext(compiled.services)
          )
      );
      expect(Array.map(dashboards, ({ uid }) => uid)).toEqual([
        "taxkit-request-overview",
        "taxkit-request-failures",
        "taxkit-request-latency",
        "taxkit-telemetry-health",
      ]);
      const queries = Array.flatMap(dashboards, ({ props }) =>
        Array.filterMap(props.dashboard.charts, (chart) =>
          Schema.decodeUnknownOption(Query)(chart)
        )
      );
      expect(queries.length).toBeGreaterThan(15);
      for (const { query } of queries) {
        expect(query.apl).toContain("['site-prod-logs']");
        expect(query.apl).toContain("Service in ('taxkit-api', 'taxkit-web')");
        expect(query.apl).not.toMatch(
          /site-prod-traces|site-prod-metrics|url|header|salary|income|gross/iu
        );
      }
    }).pipe(
      Effect.provideService(AlchemyContext, localContext),
      environment,
      Effect.scoped
    )
  );

  it.live("plans retained log and trace destinations from the token", () =>
    Effect.gen(function* () {
      const { compiled, plan, providerWrites } = yield* planned(
        "trace-export"
      );
      expect(providerWrites).toBe(0);
      expect(Array.sort(Record.keys(plan.resources), Order.String)).toEqual([
        "TaxKitAxiomLogs",
        "TaxKitAxiomTraces",
      ]);
      const destinations = yield* Effect.forEach(
        ["TaxKitAxiomLogs", "TaxKitAxiomTraces"],
        (id) =>
          Record.get(compiled.resources, id).pipe(
            Effect.fromOption,
            Effect.flatMap((resource) =>
              Output.evaluate(
                { props: resource.Props, removal: resource.RemovalPolicy },
                {}
              )
            ),
            Effect.provideContext(compiled.services)
          )
      );
      const [logs, traces] = destinations;
      expect(logs?.removal).toBe("retain");
      expect(traces?.removal).toBe("retain");
      expect({ ...logs?.props, headers: undefined }).toEqual({
        enabled: true,
        headers: undefined,
        logpushDataset: "opentelemetry-logs",
        name: "taxkit-axiom-logs",
        url: "https://axiom.example.test/v1/logs",
      });
      expect({ ...traces?.props, headers: undefined }).toEqual({
        enabled: true,
        headers: undefined,
        logpushDataset: "opentelemetry-traces",
        name: "taxkit-axiom-traces",
        url: "https://axiom.example.test/v1/traces",
      });
      expect(logs?.props.headers?.["X-Axiom-Dataset"]).toBe("site-prod-logs");
      expect(traces?.props.headers?.["X-Axiom-Dataset"]).toBe(
        "site-prod-traces"
      );
      // The bearer header comes from the retained token; compare without
      // printing it.
      expect(
        Array.every(
          destinations,
          ({ props }) =>
            props.headers?.Authorization === `Bearer ${ingestSentinel}`
        )
      ).toBe(true);
      // Workers read only the two names; headers never become outputs.
      expect(
        Array.sort(Record.keys(compiled.output), Order.String)
      ).toEqual(["logsDestinationName", "tracesDestinationName"]);
    }).pipe(
      Effect.provideService(AlchemyContext, localContext),
      environment,
      Effect.scoped
    )
  );
});

