/**
 * Alchemy's stage proxy returns a reference for every stage name, but its
 * index-signature type also admits absence. Absence is an impossible
 * invariant, reported as a defect rather than a deployment error.
 */
export class StageReferenceMissing extends Schema.TaggedError<StageReferenceMissing>()(
  "StageReferenceMissing",
  { stack: Schema.String }
) {}

/** Production's persisted `TaxKitTraceExport` outputs, read from any stage. */
export const taxKitTraceExportProduction: Effect.Effect<TaxKitTraceExport> =
  Effect.suspend(() =>
    Option.match(
      Option.fromNullishOr(TaxKitTraceExport.stage[telemetryStage]),
      {
        onNone: () =>
          Effect.die(
            new StageReferenceMissing({ stack: taxKitTraceExportStackName })
          ),
        onSome: (reference) => reference,
      }
} from "@taxkit/calculators/schemas";

